// idea from: http://rectangleworld.com/blog/archives/733
// PGraphics, line, Array, let PGraphics b1, b2;
let yPos1, yPos2;
let firstTime = true;

let palette = new Array(31);

function setup() {
  createCanvas(620, 560);
  background(0);

  for (let i = 1; i <= 30; i++) {
    palette[i] = color(255, random(255), 255);
  }
  palette[15] = palette[16] = color("#0AEDFF");

  b1 = drawRows(28);
  yPos1= 0;
  yPos2 = 560;
}

function draw() {
  frameRate(30);
  background(0);
  if (firstTime) {
    b2 = drawRows(28);
    firstTime = false;
  }

  yPos1 -= 1;
  yPos2 -= 1;

  image(b1, 0, yPos1);
  image(b2, 0, yPos2);

  if (yPos1 <= -560) {
    b1 = drawRows(28);
    yPos1 = 560;
  }
  if (yPos2 <= -560) {
    b2 = drawRows(28);
    yPos2 = 560;
  }
}

function drawRows(numRows) {
  let b = createGraphics(620, 560);
  for (let i = 0; i < numRows; i++) {
    drawRow(i, b);
  } 
  return b;
}

function drawRow(rowNum, b) {
  rowNum *= 20;
  let colNum = 1;
  while (colNum <= 30) {
    if (random(1) < .5 || frameCount == 0) drawVertical(colNum * 20, rowNum, palette[colNum], b);
    else {
      let which ;
      if (random(1) < .5) which = true;
      else which = false;
      if (colNum != 30) {
        drawCrossing(colNum * 20, rowNum, which, palette[colNum], palette[colNum+1], b);
        let hold = palette[colNum];
        palette[colNum] = palette[colNum+1];
        palette[colNum+1] = hold;
      }
      if (colNum == 30) drawVertical(colNum * 20, rowNum, palette[colNum], b);
      colNum++;
    }
    colNum++;
  }
}

function drawVertical(x, y, c, b) {
  b.beginDraw();
  b.stroke(c);
  b.strokeWeight(5);
  b.line(x, y, x, y+20);
  b.endDraw();
}

function drawCrossing(x, y, positive, c1, c2, b) {
  b.beginDraw();
  if (positive) {
    b.stroke(c1);
    b.strokeWeight(5);
    b.line(x, y, x+20, y+20);
    b.stroke(c2);
    b.line(x+20, y, x+15, y+5);
    b.line(x+5, y+15, x, y+20);
  } else {
    b.stroke(c2);
    b.strokeWeight(5);
    b.line(x+20, y, x, y+20);
    b.stroke(c1);
    b.line(x, y, x+5, y+5);
    b.line(x+15, y+15, x+20, y+20);
  }
  b.endDraw();
}
